import type { Project } from "@/sanity/lib/fetch";

// Project payload as returned by PROJECTS_QUERY (generated by Sanity typegen).
export type ProjectShowcaseData = Project;
export type ProjectImage = NonNullable<Project["images"]>[number];

// Project showcase component props
export interface ProjectShowcaseProps {
  projects: ProjectShowcaseData[];
}

export interface ProjectCardProps {
  project: ProjectShowcaseData;
}

export interface ProjectDetailsProps {
  description: string;
  isExpanded: boolean;
  wordLimit?: number;
}

export interface SkillCarouselProps {
  skillsData: string[];
  autoPlay?: boolean;
  className?: string;
}
